    .string "E_UNREACHABLE_MATCH_ARM"
.L19017:
    .string "An arm can never run, because an earlier arm already matches everything it would."
.L19018:
    .string "(defn f (o) (match o (_ 0) (Some x x)))\n(defn main () (f (Some 0)))"
.L19019:
    .string "(defn f (o) (match o (Some x x) (_ 0)))\n(defn main () (f (Some 0)))"
.L19020:
    .string "E_FFI_TIMEOUT_REQUIRED"
.L19021:
    .string "Every `ffi-call` ends with a timeout: a positive whole number of milliseconds, written literally."
.L19022:
    .string "(defn main () (begin (print (ffi-call \"zyl_cstr_len\" \"abc\" 0)) 0))"
.L19023:
    .string "(defn main () (begin (print (ffi-call \"zyl_cstr_len\" \"abc\" 1000)) 0))"
.L19024:
    .string "E_TRAIT_NOT_FOUND"
.L19025:
    .string "A trait method is used on a type that has no `impl` of that trait."
.L19026:
    .string "(defn main () (with-resource (s \"text\") (begin (print s) 0)))"
.L19027:
    .string "(defn main () (let s \"text\" (begin (print s) 0)))"
.L19028:
    .string "E_NESTED_PATTERN"
.L19029:
    .string "A constructor arm binds plain names only; match the inner value in a second `match`."
.L19030:
    .string "(defn f (o) (match o (Some (Some x) x) (_ 0)))\n(defn main () (f (Some (Some 0))))"
.L19031:
    .string "(defn f (o) (match o (Some inner (match inner (Some x x) (None 0))) (None 0)))\n(defn main () (f (Some (Some 0))))"
.L19032:
    .string "E_TRAIT_NOT_DERIVABLE"
.L19033:
    .string "`derive` names a trait it cannot write an impl for."
.L19034:
    .string "(defstruct Point (x Int))\n(derive Point Frobnicate)\n(defn main () 0)"
.L19035:
    .string "(defstruct Point (x Int))\n(derive Point Eq)\n(defn main () 0)"
.L19036:
    .string "E_MACRO_NON_TERMINATION"
.L19037:
    .string "Macro expansion never finishes: the macros expand into each other forever."
.L19038:
    .string "(defmacro ping (x) (pong x))\n(defmacro pong (x) (ping x))\n(defn main () (ping 0))"
.L19039:
    .string "(defmacro ping (x) x)\n(defn main () (ping 0))"
.L19040:
    .string "E_DUPLICATE_DEFINITION"
.L19041:
    .string "Two top-level definitions share one name."
.L19042:
    .string "(defn f (x) x)\n(defn f (x) (+ x 1))\n(defn main () (f 0))"
.L19043:
    .string "(defn f (x) x)\n(defn g (x) (+ x 1))\n(defn main () (f (- (g 0) 1)))"
.L19044:
    .string "E_SECRET_ESCAPE"
.L19045:
    .string "A `Secret` value reaches output, a file or another observable place without `declassify`."
.L19046:
    .string "(capabilities io secret)\n(use core/core)\n(defn leak ((key Secret)) (file-write 2 key))\n(defn main () (begin (leak 5) 0))"
.L19047:
    .string "(capabilities io secret)\n(use core/core)\n(defn leak ((key Secret)) (file-write 2 \"<redacted>\"))\n(defn main () (begin (leak 5) 0))"
.L19048:
    .string "E_RESERVED_KEYWORD"
.L19049:
    .string "A keyword of the language is used as a name."
.L19050:
    .string "(defn f (test) test)\n(defn main () (f 0))"
.L19051:
    .string "(defn f (t) t)\n(defn main () (f 0))"
.L19052:
    .string "E_SHADOWS_BUILTIN"
.L19053:
    .string "A local binding is named like a built-in, so a call of that name would never reach it."
.L19054:
    .string "(defn main () (let print 0 print))"
.L19055:
    .string "(defn main () (let print-value 0 print-value))"
.L19056:
    .string "E_INDEX_OUT_OF_BOUNDS"
.L19057:
    .string "An index is outside the tuple, array or buffer it reads."
.L19058:
    .string "(use core/core)\n(defn main () (let t (tuple 1 2) (begin (print (tuple-get t 5)) 0)))"
.L19059:
    .string "(use core/core)\n(defn main () (let t (tuple 1 2) (begin (print (tuple-get t 1)) 0)))"
.L19060:
    .string "E_CAPABILITY_LEAK"
.L19061:
    .string "Mutable state crosses to another actor: a captured let-mut, ByteBuf, Ref or other mutable handle, one sent over a channel, or a top-level def of one an actor reaches. Share numbers through an AtomicBuf instead."
.L19062:
    .string "(capabilities actor)\n(use actor/actor)\n(defn main () (let b (bytebuf Heap 8) (let a (spawn (fn () (store-u8! :le b 0 1))) (begin (actor-wait a) 0))))"
.L19063:
    .string "(capabilities actor)\n(use actor/actor)\n(use atomic/atomic)\n(defn main () (let b (atomicbuf-new 1) (let a (spawn (fn () (atomicbuf-add b 0 1))) (begin (actor-wait a) (- (atomicview-get! (atomicbuf-freeze! b) 0) 1)))))"
.L19064:
    .string "E_ATOMIC_SHARED"
.L19065:
    .string "An AtomicBuf is frozen while an actor that captured it has not been joined by the actor that spawned it; reading then could see a partial total."
.L19066:
    .string "(capabilities actor)\n(use actor/actor)\n(use atomic/atomic)\n(defn main () (let b (atomicbuf-new 1) (let a (spawn (fn () (atomicbuf-add b 0 1))) (let v (atomicbuf-freeze! b) (begin (actor-wait a) (atomicview-get! v 0))))))"
.L19067:
    .string "(capabilities actor)\n(use actor/actor)\n(use atomic/atomic)\n(defn main () (let b (atomicbuf-new 1) (let a (spawn (fn () (atomicbuf-add b 0 1))) (begin (actor-wait a) (- (atomicview-get! (atomicbuf-freeze! b) 0) 1)))))"
.L19068:
    .string "E_MISALIGNED_ACCESS"
.L19069:
    .string "An address atomic (atomic/atomic) at an address that is not a multiple of 8."
.L19070:
    .string "(capabilities ffi)\n(use atomic/atomic)\n(defn main () (let b (bytebuf Heap 16) (begin (atomic-store! (+ (bytebuf-ptr b) 4) 1) 0)))"
.L19071:
    .string "(capabilities ffi)\n(use atomic/atomic)\n(defn main () (let b (bytebuf Heap 16) (begin (atomic-store! (+ (bytebuf-ptr b) 8) 1) 0)))"
.L19072:
    .string "E_CT_VIOLATION"
.L19073:
    .string "A branch, index or division depends on a `Secret`, which leaks it through timing."
.L19074:
    .string "(capabilities secret)\n(use core/core)\n(defn check ((key Secret) (guess Int)) (if (= key guess) 1 0))\n(defn main () (- (check 7 7) 1))"
.L19075:
    .string "(capabilities secret)\n(use core/core)\n(use math/secret/secret)\n(defn check ((key Secret) (guess Int)) (declassify (ct-eq key guess)))\n(defn main () (- (check 7 7) 1))"
.L19076:
    .string "E_FFI_PIN_REQUIRED"
.L19077:
    .string "A `Secret` passed to foreign code must go through `ffi-pin`."
.L19078:
    .string "(capabilities ffi secret)\n(use core/core)\n(extern \"abs\" (Int) Int)\n(defn raw ((key Secret)) (ffi-call \"abs\" key 1000))\n(defn main () (begin (raw 5) 0))"
.L19079:
    .string "(capabilities ffi secret)\n(use core/core)\n(defn raw ((key Secret)) (let p (ffi-pin key) (ffi-unpin p)))\n(defn main () (begin (raw 5) 0))"
.L19080:
    .string "E_CONTRACT_EFFECT"
.L19081:
    .string "A `requires`, `ensures` or `invariant` condition does I/O, calls foreign code, uses an actor or channel, changes shared state or exits, itself or through a function it calls; the profile decides whether a condition runs, so it may only compute."
.L19082:
    .string "(defn noisy (n) (begin (print n) true))\n(defn half (n) (begin (requires (noisy n)) (div! n 2)))\n(defn main () (half 0))"
.L19083:
    .string "(defn half (n) (begin (print n) (requires (>= n 0)) (div! n 2)))\n(defn main () (half 0))"
.L19084:
    .string "E_CONTRACT_VIOLATION"
.L19085:
    .string "A `requires`, `ensures` or `invariant` check was false when it ran."
.L19086:
    .string "(defn half (n) (begin (requires (>= n 0)) (/ n 2)))\n(defn main () (half -4))"
.L19087:
    .string "(defn half (n) (begin (requires (>= n 0)) (/ n 2)))\n(defn main () (half 0))"
.L19088:
    .string "E_REGION_EXHAUSTED"
.L19089:
    .string "A `with-region` region ran out of the space its `:size` or `:limit` gives it."
.L19090:
    .string "(defn main () (with-region (fixed :size 64) (begin (print (str-length (str-concat \"a\" (str-concat \"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\" \"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc\")))) 0)))"
.L19091:
    .string "(defn main () (with-region (fixed :size 4096) (begin (print (str-length (str-concat \"a\" (str-concat \"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\" \"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc\")))) 0)))"
.L19092:
    .string "E_CHANNEL_CLOSED"
.L19093:
    .string "`chan-recv` on a channel whose sender has finished and whose values are all taken."
.L19094:
    .string "(capabilities actor)\n(use actor/actor)\n(defn main () (let c (chan 1) (let rx (chan-rx c) (let tx (chan-tx c) (let a (spawn (fn () (chan-send tx 7))) (begin (actor-wait a) (print (chan-recv rx)) (print (chan-recv rx)) 0))))))"
.L19095:
    .string "(capabilities actor)\n(use actor/actor)\n(defn main () (let c (chan 1) (let rx (chan-rx c) (let tx (chan-tx c) (let a (spawn (fn () (chan-send tx 7))) (begin (actor-wait a) (print (chan-recv rx)) 0))))))"
.L19096:
    .string "E_FFI_TIMEOUT"
.L19097:
    .string "A foreign call ran longer than its timeout; it is abandoned and this error raised."
.L19098:
    .string "(capabilities ffi)\n(extern \"usleep\" (Int) Int)\n(defn main () (begin (ffi-call \"usleep\" 300000 50) 0))"
.L19099:
    .string "(capabilities ffi)\n(extern \"usleep\" (Int) Int)\n(defn main () (begin (ffi-call \"usleep\" 1000 1000) 0))"
.L19100:
    .string "E_DUPLICATE_PARAMETER"
.L19101:
    .string "A function declares the same parameter name twice."
.L19102:
    .string "(defn f (a a) a)\n(defn main () (f 0 0))"
.L19103:
    .string "(defn f (a b) (+ a b))\n(defn main () (f 0 0))"
.L19104:
    .string "E_OVERFLOW"
.L19105:
    .string "An Int `+`, `-` or `*` whose result does not fit, or the smallest Int divided by -1."
.L19106:
    .string "(defn grow (n) (* n 4))\n(defn main () (begin (print (grow 9223372036854775807)) 0))"
.L19107:
    .string "(defn grow (n) (saturating* n 4))\n(defn main () (begin (print (grow 9223372036854775807)) 0))"
.L19108:
    .string "E_PARTIAL_OPERATION"
.L19109:
    .string "An Int `/` or `%` whose divisor is not a nonzero literal, so it could be zero."
.L19110:
    .string "(defn mean (t n) (/ t n))\n(defn main () (mean 10 2))"
.L19111:
    .string "(defn mean (t n) (match (div? t n) (Some q q) (None 0)))\n(defn main () (begin (print (mean 10 0)) 0))"
.L19112:
    .string "E_DIVISION_BY_ZERO"
.L19113:
    .string "`div!` or `rem!` met a zero divisor."
.L19114:
    .string "(defn per (t n) (div! t n))\n(defn main () (begin (print (per 10 0)) 0))"
.L19115:
    .string "(defn per (t n) (match (div? t n) (Some q q) (None 0)))\n(defn main () (begin (print (per 10 0)) 0))"
.L19116:
    .string "E_INTEGER_OVERFLOW"
.L19117:
    .string "An integer literal does not fit in a 64-bit Int."
.L19118:
    .string "(defn main () (begin (print 99999999999999999999) 0))"
.L19119:
    .string "(defn main () (begin (print 9223372036854775807) 0))"
